import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_svg/flutter_svg.dart';

import '../../../../l10n/l10n.dart';
import '../../../../pages/wallet_view/sub_widgets/wallet_balance_toggle_sheet.dart';
import '../../../../pages/wallet_view/sub_widgets/wallet_refresh_button.dart';
import '../../../../providers/providers.dart';
import '../../../../providers/wallet/public_private_balance_state_provider.dart';
import '../../../../providers/wallet/wallet_balance_toggle_state_provider.dart';
import '../../../../services/event_bus/events/global/wallet_sync_status_changed_event.dart';
import '../../../../themes/stack_colors.dart';
import '../../../../utilities/amount/amount.dart';
import '../../../../utilities/amount/amount_formatter.dart';
import '../../../../utilities/assets.dart';
import '../../../../utilities/enums/wallet_balance_toggle_state.dart';
import '../../../../utilities/text_styles.dart';
import '../../../../wallets/isar/providers/wallet_info_provider.dart';
import '../../../../wallets/wallet/impl/pivx_wallet.dart';
import '../../../../widgets/desktop/desktop_dialog.dart';
import 'desktop_balance_toggle_button.dart';

class DesktopWalletSummary extends ConsumerStatefulWidget {
  const DesktopWalletSummary({
    super.key,
    required this.walletId,
    required this.initialSyncStatus,
  });

  final String walletId;
  final WalletSyncStatus initialSyncStatus;

  @override
  ConsumerState<DesktopWalletSummary> createState() =>
      _WDesktopWalletSummaryState();
}

class _WDesktopWalletSummaryState extends ConsumerState<DesktopWalletSummary> {
  late final String walletId;

  @override
  void initState() {
    super.initState();
    walletId = widget.walletId;
  }

  @override
  Widget build(BuildContext context) {
    debugPrint("BUILD: $runtimeType");

    final externalCalls = ref.watch(
      prefsChangeNotifierProvider.select((value) => value.externalCalls),
    );

    final locale = ref.watch(
      localeServiceChangeNotifierProvider.select((value) => value.locale),
    );

    final baseCurrency = ref.watch(
      prefsChangeNotifierProvider.select((value) => value.currency),
    );

    final coin = ref.watch(pWalletCoin(walletId));
    final price = ref.watch(
      priceAnd24hChangeNotifierProvider.select((value) => value.getPrice(coin)),
    );

    final _showAvailable =
        ref.watch(walletBalanceToggleStateProvider) ==
        WalletBalanceToggleState.available;

    final balance = ref.watch(pWalletBalance(walletId));
    Amount balanceToShow = _showAvailable ? balance.spendable : balance.total;

    // PIVX has a transparent and a shield balance: the same choice as on
    // mobile (total, or one of them available or in full).
    final wallet = ref.watch(pWallets).getWallet(walletId);
    final pivxShield = wallet is PivxWallet && wallet.supportsShield;
    String? title;
    if (pivxShield) {
      final type = ref.watch(publicPrivateBalanceStateProvider);
      final privateBalance = ref.watch(pWalletBalanceSecondary(walletId));
      if (ref.watch(showTotalBalanceProvider)) {
        title = l10n.balanceTotal;
        balanceToShow = balance.total + privateBalance.total;
      } else {
        title = switch ((_showAvailable, type == BalanceType.private)) {
          (true, true) => l10n.balanceAvailableShielded,
          (false, true) => l10n.balanceFullShielded,
          (true, false) => l10n.balanceAvailableTransparent,
          (false, false) => l10n.balanceFullTransparent,
        };
        final selected = type == BalanceType.private ? privateBalance : balance;
        balanceToShow = _showAvailable ? selected.spendable : selected.total;
      }
    }

    return Consumer(
      builder: (context, ref, __) {
        return Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                if (title != null)
                  // As on mobile: the title opens the balance choice.
                  MouseRegion(
                    cursor: SystemMouseCursors.click,
                    child: GestureDetector(
                      onTap: () => showDialog<void>(
                        context: context,
                        builder: (_) => DesktopDialog(
                          maxWidth: 480,
                          maxHeight: double.infinity,
                          child: WalletBalanceToggleSheet(walletId: walletId),
                        ),
                      ),
                      child: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Text(
                            title,
                            style: STextStyles.desktopTextExtraExtraSmall(
                              context,
                            ),
                          ),
                          const SizedBox(width: 6),
                          SvgPicture.asset(
                            Assets.svg.chevronDown,
                            width: 10,
                            height: 5,
                            colorFilter: ColorFilter.mode(
                              Theme.of(context)
                                  .extension<StackColors>()!
                                  .textSubtitle1,
                              BlendMode.srcIn,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                FittedBox(
                  fit: BoxFit.scaleDown,
                  child: SelectableText(
                    ref.watch(pAmountFormatter(coin)).format(balanceToShow),
                    style: STextStyles.desktopH3(context),
                  ),
                ),
                if (externalCalls && price != null)
                  SelectableText(
                    "${Amount.fromDecimal(price.value * balanceToShow.decimal, fractionDigits: 2).fiatString(locale: locale)} $baseCurrency",
                    style: STextStyles.desktopTextExtraSmall(context).copyWith(
                      color: Theme.of(context)
                          .extension<StackColors>()!
                          .textSubtitle1,
                    ),
                  ),
              ],
            ),
            const SizedBox(width: 8),
            WalletRefreshButton(
              walletId: walletId,
              initialSyncStatus: widget.initialSyncStatus,
            ),

            if (!pivxShield) ...[
              const SizedBox(width: 8),
              const DesktopBalanceToggleButton(),
            ],
          ],
        );
      },
    );
  }
}
